-- Bootstrap lazy.nvim
local lazypath = vim.fn.stdpath("data") .. "/lazy/lazy.nvim"
if not vim.loop.fs_stat(lazypath) then
  vim.fn.system({
    "git",
    "clone",
    "--filter=blob:none",
    "https://github.com/folke/lazy.nvim.git",
    lazypath,
  })
end
vim.opt.rtp:prepend(lazypath)

-- Editor UI settings
vim.opt.number = true
vim.opt.relativenumber = true
vim.opt.termguicolors = true
vim.opt.expandtab = true
vim.opt.tabstop = 2
vim.opt.shiftwidth = 2
vim.opt.smartindent = true
vim.opt.syntax = "on"
vim.opt.background = "dark"

-- Disable unused providers
vim.g.loaded_perl_provider = 0

-- Filetype override for .qmd
vim.api.nvim_create_autocmd({ "BufRead", "BufNewFile" }, {
  pattern = "*.qmd",
  callback = function()
    vim.bo.filetype = "markdown"
  end,
})

-- Keymaps
vim.keymap.set("n", "<F5>", ":!quarto preview %<CR>", { noremap = true })
vim.keymap.set("n", "<leader>f", ":Telescope find_files<CR>")

-- Load plugins
require("lazy").setup({
  { "nvim-lua/plenary.nvim" },
  {
    "folke/tokyonight.nvim",
    lazy = false,
    priority = 1000,
  },
  { "tpope/vim-fugitive" },
  {
    "nvim-treesitter/nvim-treesitter",
    build = ":TSUpdate",
    config = function()
      require("nvim-treesitter.configs").setup({
        ensure_installed = {
          "lua", "python", "markdown", "markdown_inline", "bibtex", "latex", "json", "yaml"
        },
        highlight = { enable = true },
        indent = { enable = true },
        incremental_selection = {
          enable = true,
          keymaps = {
            init_selection = "<CR>",
            node_incremental = "<CR>",
            scope_incremental = "<TAB>",
            node_decremental = "<BS>",
          },
        },
        textobjects = {
          select = {
            enable = true,
            keymaps = {
              ["af"] = "@function.outer",
              ["if"] = "@function.inner",
              ["ac"] = "@class.outer",
              ["ic"] = "@class.inner",
            },
          },
        },
      })
    end,
  },
  { "nvim-lualine/lualine.nvim", dependencies = { "nvim-tree/nvim-web-devicons" } },
  { "nvim-telescope/telescope.nvim", tag = "0.1.3", dependencies = { "nvim-lua/plenary.nvim" } },
  { "iamcco/markdown-preview.nvim", build = "cd app && npm install", ft = { "markdown", "quarto" } },
  { "folke/tokyonight.nvim", lazy = false, priority = 1000 },
})

vim.cmd.colorscheme("tokyonight")

