content.text:
vim.api.nvim_create_autocmd({ "BufRead", "BufNewFile" }, {
  pattern = "*.qmd",
  callback = function()
    vim.bo.filetype = "quarto"
  end,
})

return {
  {
    "nvim-treesitter/nvim-treesitter",
    build = ":TSUpdate",
    config = function()
      require("nvim-treesitter.configs").setup({
        ensure_installed = {
          "lua",
          "python",
          "markdown",
          "markdown_inline",
          "bibtex",
          "latex",
          "json",
          "yaml",
        },
        -- Treesitter highlighting is disabled for now because Neovim 0.12.3
        -- is tripping over a parser/highlighter mismatch in this setup.
        highlight = { enable = false },
        indent = { enable = true },
        incremental_selection = {
          enable = true,
          keymaps = {
            init_selection = "<CR>",
            node_incremental = "<CR>",
            scope_incremental = "<TAB>",
            node_decremental = "<BS>",
          },
        },
        textobjects = {
          select = {
            enable = true,
            keymaps = {
              ["af"] = "@function.outer",
              ["if"] = "@function.inner",
              ["ac"] = "@class.outer",
              ["ic"] = "@class.inner",
            },
          },
        },
      })
    end,
  },
  {
    "iamcco/markdown-preview.nvim",
    build = "cd app && npm install",
    ft = { "markdown", "quarto" },
  },
}

return {
  {
    "folke/tokyonight.nvim",
    lazy = false,
    priority = 1000,
  },
  {
    "nvim-lualine/lualine.nvim",
    lazy = false,
    dependencies = { "nvim-tree/nvim-web-devicons" },
    opts = {
      options = {
        theme = "tokyonight",
      },
    },
  },
  {
    "nvim-telescope/telescope.nvim",
    tag = "0.1.3",
    cmd = "Telescope",
    dependencies = { "nvim-lua/plenary.nvim" },
  },
}

